// A skill mark. Simple Icons marks sit on a 24 unit grid and are drawn in one brand colour; a mark from elsewhere
// brings its own square view box and, if the glyph has holes, an even-odd fill rule.
export type SkillGradient = {
  id: string;
  stops: { offset: string; color: string; opacity?: string }[];
  x1?: string;
  y1?: string;
  x2?: string;
  y2?: string;
  cx?: string;
  cy?: string;
  r?: string;
  fx?: string;
  fy?: string;
  gradientUnits?: "userSpaceOnUse" | "objectBoundingBox";
  gradientTransform?: string;
  // A radial gradient is drawn from cx/cy/r instead of the x1/y1/x2/y2 line.
  radial?: boolean;
};

// One path of a mark. 'fill' is a fixed brand colour (#rrggbb), a gradient (url(#id)), or absent to take the
// per-theme logo fill, which is how a monochrome mark inverts between the light and dark surfaces.
export type SkillLayer = {
  path: string;
  fill?: string;
  transform?: string;
  fillRule?: "evenodd";
  opacity?: string;
};

export type SkillIcon = Pick<SimpleIcon, "title" | "slug" | "hex"> & {
  // The single-colour outline, for marks that are not layered. A layered mark describes itself in 'layers'.
  path?: string;
  viewBox?: string;
  fillRule?: "evenodd";
  layers?: SkillLayer[];
  gradients?: SkillGradient[];
};

